 static TextBlock Heading(string text)=>new(){Text=text,FontWeight=FontWeights.Bold,Margin=new(0,8,0,6)};
 static DockPanel LabelRow(string label,FrameworkElement control){var row=new DockPanel{MinHeight=32};row.Children.Add(new TextBlock{Text=label,Width=89,VerticalAlignment=VerticalAlignment.Center});row.Children.Add(control);return row;}
 FrameworkElement InputRow(string label,string port){var button=new Button{Content=context.InputLabel?.Invoke(port)??"------",Tag="ImageBinaryInput:"+port,HorizontalContentAlignment=HorizontalAlignment.Left,IsEnabled=context.EditInput is not null};button.Click+=(_,_)=>{try{context.EditInput?.Invoke(port,this);button.Content=context.InputLabel?.Invoke(port)??"------";LastResult=null;images.ItemsSource=new[]{"输入图像"};images.SelectedIndex=0;roi.SetImage(context.PreviewImage?.Invoke());}catch(Exception e){status.Text=e.Message;}};inputButtons.Add(button);return LabelRow(label,button);}
 FrameworkElement BuildRunParameters(){thresholdInputs.Clear();var panel=new StackPanel{Margin=new(32,1,32,0)};var modes=new ComboBox{Tag="ImageBinaryMode",Height=30};foreach(var pair in new[]{("硬阈值",1),("均值",2),("高斯",3),("Sauvola",8),("自动阈值",4)})modes.Items.Add(new ComboBoxItem{Content=pair.Item1,Tag=pair.Item2,IsEnabled=pair.Item2==1,ToolTip=pair.Item2==1?null:"独立算法尚未完成验证"});modes.SelectedItem=modes.Items.OfType<ComboBoxItem>().FirstOrDefault(i=>Equals(i.Tag,values["BinaryType"].GetInt32()));modes.SelectionChanged+=(_,_)=>{if(modes.SelectedItem is ComboBoxItem item&&item.IsEnabled){values["BinaryType"]=JsonSerializer.SerializeToElement((int)item.Tag);CommitLive();}};panel.Children.Add(LabelRow("二值化类型",modes));var outside=new ComboBox{ItemsSource=new[]{"置黑","保留原图"},SelectedIndex=values["NonROIPrcType"].GetInt32(),Height=30,Tag="ImageBinaryOutside"};outside.SelectionChanged+=(_,_)=>{values["NonROIPrcType"]=JsonSerializer.SerializeToElement(outside.SelectedIndex);CommitLive();};panel.Children.Add(LabelRow("ROI外处理",outside));foreach(var key in new[]{"LowThreshold","HighThreshold"}){var field=new RoiNumericField(values[key].GetInt32(),0,255,true);field.ValueCommitted+=(_,_)=>CommitLive();thresholdInputs[key]=field.Input;field.Input.Tag="ImageBinaryField:"+key;panel.Children.Add(LabelRow(key=="LowThreshold"?"低阈值":"高阈值",field));}return panel;}
 FrameworkElement BuildDisplayParameters(){var panel=new StackPanel{Margin=new(32,1,32,0)};var visibility=new CheckBox{Content="显示ROI",IsChecked=true,Tag="ImageBinaryRoiVisible"};visibility.Click+=(_,_)=>roi.ShowRegions=visibility.IsChecked==true;panel.Children.Add(visibility);return panel;}
 void CommitLive(){if(!ready||applying||context.Session?.IsBusy==true)return;try{Apply();}catch(Exception e){status.Text=e.Message;}}
 void Apply(){if(applying)return;applying=true;try{foreach(var field in thresholdInputs){if(!int.TryParse(field.Value.Text,out var n)||n<0||n>255)throw new InvalidDataException("阈值必须为0到255的整数："+field.Key);values[field.Key]=JsonSerializer.SerializeToElement(n);}roi.CommitPending();RoiGeometry.ValidateForEditor(roi.Regions,ImageBinaryPlugin.RoiCapabilities);if(values["LowThreshold"].GetInt32()>values["HighThreshold"].GetInt32())throw new InvalidDataException("低阈值不能大于高阈值。");(context.ApplyConfiguration??throw new InvalidOperationException("宿主未接入ROI配置写入。"))(values,roi.Regions);}finally{applying=false;}}
 void Busy(bool value){run.IsEnabled=repeat.IsEnabled=!value;repeat.Visibility=value?Visibility.Collapsed:Visibility.Visible;stop.Visibility=value?Visibility.Visible:Visibility.Collapsed;parameterTabs.IsEnabled=!value;foreach(var button in inputButtons)button.IsEnabled=!value&&context.EditInput is not null;}
 void Present(NodeRunRecord result){if(closed)return;LastResult=result;history.Add(new(++executionIndex,DateTime.Now.ToString("HH:mm:ss.fff"),result.Status+" · "+result.Message));if(history.Count>256)history.RemoveAt(0);if(context.Session?.State==ToolDebugState.RunningContinuous&&presentationClock.ElapsedMilliseconds<100)return;presentationClock.Restart();showing=true;images.ItemsSource=new[]{"输入图像"}.Concat(result.Outputs.Where(p=>p.Value.Kind==DataKind.GrayImage).Select(p=>p.Key=="Image"?"输出图像":p.Key)).ToArray();images.SelectedIndex=result.Outputs.ContainsKey("Image")?1:0;showing=false;resultGrid.ItemsSource=result.Outputs.Select(p=>new{名称=p.Key,值=p.Value.Value is VisionCore.GrayImage image?$"{image.Width} × {image.Height}":p.Value.Value.ToString()}).ToArray();status.Text=result.Status+" · "+result.Message;ShowSelectedImage();}
 void ShowSelectedImage(){if(showing)return;string key=images.SelectedItem as string??"输入图像";if(key=="输入图像")roi.SetImage(context.PreviewImage?.Invoke());else if(LastResult?.Outputs.TryGetValue(key=="输出图像"?"Image":key,out var image)==true)roi.SetImage(image.As<VisionCore.GrayImage>());}
 public async Task RunAsync(){Busy(true);try{Apply();Present(await context.Run(values));}catch(Exception e){status.Text=e.Message;}finally{Busy(false);}}
 public async Task RunContinuousAsync(){if(context.Session is not {} session){status.Text="调试会话不可用。";return;}Busy(true);try{Apply();await session.RunContinuousAsync(()=>values,Present);}catch(OperationCanceledException){}catch(Exception e){status.Text=e.Message;}finally{Busy(false);}}
 void DragTitle(object sender,MouseButtonEventArgs e){if(e.ClickCount==2)Maximize(sender,e);else if(e.LeftButton==MouseButtonState.Pressed)DragMove();}
